func NewVipPoolsValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (VipPoolsValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing VipPoolsValue Attribute Value",
				"While creating a VipPoolsValue value, a missing attribute value was detected. "+
					"A VipPoolsValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("VipPoolsValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid VipPoolsValue Attribute Type",
				"While creating a VipPoolsValue value, an invalid attribute value was detected. "+
					"A VipPoolsValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("VipPoolsValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("VipPoolsValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra VipPoolsValue Attribute Value",
				"While creating a VipPoolsValue value, an extra attribute value was detected. "+
					"A VipPoolsValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra VipPoolsValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewVipPoolsValueUnknown(), diags
	}

	if diags.HasError() {
		return NewVipPoolsValueUnknown(), diags
	}

	return VipPoolsValue{
		state: attr.ValueStateKnown,
	}, diags
}

func NewVipPoolsValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) VipPoolsValue {
	object, diags := NewVipPoolsValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewVipPoolsValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

